<style>
*,*::before,*::after{box-sizing:border-box;margin:0;padding:0}
:root{
  --brand-primary:oklch(55% 0.22 265);
  --brand-primary-hover:oklch(48% 0.24 265);
  --brand-primary-light:oklch(95% 0.04 265);
  --brand-primary-subtle:oklch(97% 0.02 265);
  --text-primary:oklch(15% 0.01 265);
  --text-secondary:oklch(45% 0.02 265);
  --text-tertiary:oklch(62% 0.015 265);
  --bg-page:oklch(98.5% 0.003 265);
  --bg-surface:oklch(100% 0 0);
  --bg-elevated:oklch(100% 0 0);
  --border-default:oklch(92% 0.01 265);
  --border-subtle:oklch(95% 0.005 265);
  --shadow-sm:0 1px 2px oklch(0% 0 0 / 0.05);
  --shadow-md:0 4px 12px oklch(0% 0 0 / 0.08);
  --shadow-lg:0 8px 30px oklch(0% 0 0 / 0.1);
  --radius-sm:6px;
  --radius-md:8px;
  --radius-lg:12px;
  --radius-xl:16px;
  --font-sans:'Inter',-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif;
}
html{font-size:16px;-webkit-font-smoothing:antialiased;-moz-osx-font-smoothing:grayscale}
body{font-family:var(--font-sans);background:var(--bg-page);color:var(--text-primary);line-height:1.6;overflow-x:hidden}
a{color:inherit;text-decoration:none}
button{font-family:inherit;cursor:pointer;border:none;background:none}
img{display:block;max-width:100%}
ul{list-style:none}

/* ── Header ── */
.site-header{background:var(--bg-elevated);border-bottom:1px solid var(--border-default);position:sticky;top:0;z-index:100}
.header-inner{max-width:1280px;margin:0 auto;padding:0 24px;display:flex;align-items:center;justify-content:space-between;height:64px}
.header-left{display:flex;align-items:center;gap:32px}
.logo{display:flex;align-items:center;gap:8px;font-weight:700;font-size:18px;color:var(--text-primary)}
.logo svg{width:28px;height:28px}
.nav-links{display:flex;align-items:center;gap:4px}
.nav-item{position:relative}
.nav-trigger{display:flex;align-items:center;gap:4px;padding:8px 12px;font-size:14px;font-weight:500;color:var(--text-secondary);border-radius:var(--radius-sm);transition:color .15s,background .15s}
.nav-trigger:hover{color:var(--text-primary);background:var(--brand-primary-subtle)}
.nav-trigger svg{width:14px;height:14px;transition:transform .2s}
.nav-item.open .nav-trigger svg{transform:rotate(180deg)}
.nav-item.open .nav-trigger{color:var(--brand-primary);background:var(--brand-primary-light)}
.nav-link{padding:8px 12px;font-size:14px;font-weight:500;color:var(--text-secondary);border-radius:var(--radius-sm);transition:color .15s,background .15s}
.nav-link:hover{color:var(--text-primary);background:var(--brand-primary-subtle)}
.header-right{display:flex;align-items:center;gap:8px}
.btn-ask-ai{display:flex;align-items:center;gap:6px;padding:7px 14px;font-size:13px;font-weight:600;color:var(--brand-primary);border:1px solid oklch(55% 0.22 265 / 0.3);border-radius:var(--radius-md);transition:all .15s}
.btn-ask-ai:hover{background:var(--brand-primary-light);border-color:var(--brand-primary)}
.btn-ask-ai svg{width:14px;height:14px}
.btn-login{padding:7px 14px;font-size:13px;font-weight:500;color:var(--text-secondary);border-radius:var(--radius-md);transition:color .15s}
.btn-login:hover{color:var(--text-primary)}
.btn-signup{padding:7px 16px;font-size:13px;font-weight:600;color:#fff;background:var(--text-primary);border-radius:var(--radius-md);transition:background .15s}
.btn-signup:hover{background:oklch(22% 0.01 265)}

/* ── Mega Menu ── */
.mega-menu{position:absolute;top:calc(100% + 4px);left:50%;transform:translateX(-50%);min-width:680px;background:var(--bg-elevated);border:1px solid var(--border-default);border-radius:var(--radius-lg);box-shadow:var(--shadow-lg);padding:24px 28px;opacity:0;visibility:hidden;transition:opacity .2s,visibility .2s;pointer-events:none}
.nav-item.open .mega-menu{opacity:1;visibility:visible;pointer-events:auto}
.mega-menu.resources-menu{min-width:420px}
.mega-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}
.mega-section-title{font-size:11px;font-weight:600;text-transform:uppercase;letter-spacing:0.08em;color:var(--text-tertiary);padding:8px 12px 4px}
.mega-link{display:block;padding:10px 12px;border-radius:var(--radius-md);transition:background .12s}
.mega-link:hover{background:var(--brand-primary-subtle)}
.mega-link-title{font-size:13px;font-weight:600;color:var(--text-primary);margin-bottom:2px}
.mega-link-desc{font-size:12px;color:var(--text-tertiary);line-height:1.4}

/* ── Main Content ── */
.main-content{max-width:1280px;margin:0 auto;padding:0 24px}

/* ── Hero Banner ── */
.hero-banner{padding:48px 0 8px;text-align:center}
.hero-badge{display:inline-flex;align-items:center;gap:6px;padding:6px 14px;font-size:12px;font-weight:600;color:var(--brand-primary);background:var(--brand-primary-light);border-radius:999px;margin-bottom:16px}
.hero-badge svg{width:14px;height:14px}
.hero-title{font-size:40px;font-weight:800;line-height:1.15;letter-spacing:-0.025em;color:var(--text-primary);margin-bottom:12px}
.hero-subtitle{font-size:17px;color:var(--text-secondary);max-width:560px;margin:0 auto;line-height:1.6}

/* ── Category Filters ── */
.filters-section{padding:32px 0 24px;display:flex;flex-wrap:wrap;align-items:center;gap:12px;position:sticky;top:64px;background:var(--bg-page);z-index:50;border-bottom:1px solid var(--border-subtle)}
.filter-pills{display:flex;flex-wrap:wrap;gap:8px;flex:1}
.pill{padding:7px 16px;font-size:13px;font-weight:500;color:var(--text-secondary);background:var(--bg-surface);border:1px solid var(--border-default);border-radius:999px;transition:all .15s;white-space:nowrap}
.pill:hover{color:var(--text-primary);border-color:oklch(80% 0.02 265);background:oklch(97% 0.01 265)}
.pill.active{color:#fff;background:var(--text-primary);border-color:var(--text-primary)}
.search-box{position:relative;width:240px;flex-shrink:0}
.search-box input{width:100%;padding:8px 12px 8px 36px;font-size:13px;font-family:var(--font-sans);color:var(--text-primary);background:var(--bg-surface);border:1px solid var(--border-default);border-radius:var(--radius-md);outline:none;transition:border-color .15s,box-shadow .15s}
.search-box input::placeholder{color:var(--text-tertiary)}
.search-box input:focus{border-color:var(--brand-primary);box-shadow:0 0 0 3px oklch(55% 0.22 265 / 0.12)}
.search-box svg{position:absolute;left:10px;top:50%;transform:translateY(-50%);width:16px;height:16px;color:var(--text-tertiary);pointer-events:none}

/* ── Featured Articles ── */
.featured-section{padding:0 0 40px}
.featured-grid{display:grid;grid-template-columns:1fr 1fr;gap:20px}
.featured-card{background:var(--bg-elevated);border:1px solid var(--border-default);border-radius:var(--radius-xl);overflow:hidden;transition:border-color .2s,box-shadow .2s}
.featured-card:hover{border-color:oklch(80% 0.03 265);box-shadow:var(--shadow-md)}
.featured-card.large{grid-row:span 2;display:flex;flex-direction:column}
.featured-card.large .featured-body{flex:1;display:flex;flex-direction:column}
.featured-card.large .featured-title{font-size:22px}
.featured-card.large .featured-excerpt{font-size:15px}
.featured-visual{height:200px;position:relative;overflow:hidden}
.featured-card.large .featured-visual{height:280px;flex-shrink:0}
.featured-visual-bg{position:absolute;inset:0}
.featured-stats-overlay{position:absolute;bottom:16px;left:16px;right:16px;display:flex;gap:12px}
.stat-chip{padding:6px 12px;font-size:12px;font-weight:600;color:#fff;background:oklch(15% 0.01 265 / 0.75);backdrop-filter:blur(8px);border-radius:var(--radius-sm);border:1px solid oklch(100% 0 0 / 0.1)}
.featured-body{padding:20px 24px 24px}
.featured-meta{display:flex;align-items:center;gap:8px;margin-bottom:10px}
.featured-date{font-size:13px;color:var(--text-tertiary)}
.featured-title{font-size:18px;font-weight:700;line-height:1.3;letter-spacing:-0.01em;margin-bottom:8px;color:var(--text-primary);transition:color .15s}
.featured-card:hover .featured-title{color:var(--brand-primary)}
.featured-excerpt{font-size:14px;color:var(--text-secondary);line-height:1.6;margin-bottom:16px;display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden}
.featured-card.large .featured-excerpt{-webkit-line-clamp:5}
.featured-author{display:flex;align-items:center;gap:10px;margin-top:auto}
.author-avatar{width:32px;height:32px;border-radius:50%;background:var(--brand-primary-light);display:flex;align-items:center;justify-content:center;font-size:13px;font-weight:600;color:var(--brand-primary);flex-shrink:0}
.author-name{font-size:13px;font-weight:500;color:var(--text-primary)}

/* ── Visual backgrounds for featured cards ── */
.visual-agentic{background:linear-gradient(135deg,oklch(20% 0.06 265),oklch(40% 0.15 265),oklch(55% 0.22 265))}
.visual-durable{background:linear-gradient(135deg,oklch(30% 0.04 180),oklch(50% 0.12 200),oklch(60% 0.18 220))}
.visual-agent{background:linear-gradient(135deg,oklch(25% 0.05 40),oklch(50% 0.14 50),oklch(65% 0.16 55))}
.visual-pattern{position:absolute;inset:0;opacity:0.08;background-image:radial-gradient(circle at 25% 25%,#fff 1px,transparent 1px),radial-gradient(circle at 75% 75%,#fff 1px,transparent 1px);background-size:24px 24px}
.visual-icon{position:absolute;top:50%;left:50%;transform:translate(-50%,-50%);width:64px;height:64px;opacity:0.15}

/* ── Latest News ── */
.latest-section{padding:0 0 48px}
.section-heading{display:flex;align-items:center;justify-content:space-between;margin-bottom:24px}
.section-title{font-size:22px;font-weight:700;letter-spacing:-0.01em}
.posts-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:20px}
.post-card{background:var(--bg-elevated);border:1px solid var(--border-default);border-radius:var(--radius-lg);padding:20px 22px 22px;transition:border-color .2s,box-shadow .2s,transform .2s}
.post-card:hover{border-color:oklch(80% 0.03 265);box-shadow:var(--shadow-md);transform:translateY(-2px)}
.post-category{display:inline-block;padding:4px 10px;font-size:11px;font-weight:600;text-transform:uppercase;letter-spacing:0.04em;color:var(--brand-primary);background:var(--brand-primary-light);border-radius:999px;margin-bottom:12px}
.post-date{font-size:13px;color:var(--text-tertiary);margin-bottom:8px}
.post-title{font-size:16px;font-weight:700;line-height:1.35;letter-spacing:-0.005em;margin-bottom:8px;color:var(--text-primary);transition:color .15s}
.post-card:hover .post-title{color:var(--brand-primary)}
.post-excerpt{font-size:13.5px;color:var(--text-secondary);line-height:1.55;margin-bottom:16px;display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden}
