.btn-show-more{display:inline-flex;align-items:center;gap:8px;padding:12px 28px;font-size:14px;font-weight:600;color:var(--text-primary);background:var(--bg-surface);border:1px solid var(--border-default);border-radius:var(--radius-md);transition:all .15s}
.btn-show-more:hover{border-color:var(--text-primary);background:oklch(97% 0.01 265)}
.btn-show-more svg{width:16px;height:16px}

/* ── No Results ── */
.no-results{text-align:center;padding:64px 24px;display:none}
.no-results.visible{display:block}
.no-results-icon{width:48px;height:48px;margin:0 auto 16px;color:var(--text-tertiary);opacity:0.5}
.no-results-text{font-size:15px;color:var(--text-secondary);max-width:360px;margin:0 auto}

/* ── CTA Banner ── */
.cta-section{background:var(--text-primary);border-radius:var(--radius-xl);margin:0 0 64px;padding:56px 48px;display:flex;gap:48px;align-items:center;justify-content:space-between}
.cta-main{flex:1;max-width:560px}
