.cta-subtext{font-size:15px;color:oklch(70% 0.01 265);margin-bottom:24px}
.cta-buttons{display:flex;gap:12px;flex-wrap:wrap}
.btn-primary{padding:11px 24px;font-size:14px;font-weight:600;color:#fff;background:var(--brand-primary);border-radius:var(--radius-md);transition:background .15s}
.btn-primary:hover{background:var(--brand-primary-hover)}
.btn-secondary{padding:11px 24px;font-size:14px;font-weight:600;color:oklch(85% 0.005 265);background:transparent;border:1px solid oklch(45% 0.01 265);border-radius:var(--radius-md);transition:all .15s}
.btn-secondary:hover{border-color:oklch(65% 0.01 265);color:#fff}
.cta-enterprise{flex-shrink:0;padding:32px;background:oklch(22% 0.01 265);border-radius:var(--radius-lg);max-width:320px}
.cta-enterprise-title{font-size:15px;font-weight:600;color:#fff;margin-bottom:8px}
.cta-enterprise-desc{font-size:13px;color:oklch(65% 0.01 265);line-height:1.5;margin-bottom:20px}
.btn-enterprise{display:inline-flex;padding:9px 20px;font-size:13px;font-weight:600;color:#fff;background:oklch(30% 0.01 265);border:1px solid oklch(40% 0.01 265);border-radius:var(--radius-md);transition:all .15s}
.btn-enterprise:hover{background:oklch(35% 0.01 265);border-color:oklch(50% 0.01 265)}

/* ── Footer ── */
.site-footer{border-top:1px solid var(--border-default);background:var(--bg-elevated)}
.footer-inner{max-width:1280px;margin:0 auto;padding:48px 24px 32px}
.footer-grid{display:grid;grid-template-columns:repeat(5,1fr);gap:32px;margin-bottom:40px}
.footer-col-title{font-size:12px;font-weight:600;text-transform:uppercase;letter-spacing:0.08em;color:var(--text-primary);margin-bottom:12px}
.footer-col ul li{margin-bottom:6px}
.footer-col a{font-size:13px;color:var(--text-secondary);transition:color .12s}
