.footer-bottom{display:flex;align-items:center;justify-content:space-between;padding-top:24px;border-top:1px solid var(--border-default)}
.footer-bottom-left{display:flex;align-items:center;gap:8px;font-size:13px;color:var(--text-tertiary)}
.status-dot{width:7px;height:7px;border-radius:50%;background:oklch(65% 0.2 145)}
.footer-social{display:flex;gap:16px}
.footer-social a{color:var(--text-tertiary);transition:color .12s}
.footer-social a:hover{color:var(--text-primary)}
.footer-social svg{width:18px;height:18px}

/* ── Responsive ── */
@media(max-width:1024px){
  .featured-grid{grid-template-columns:1fr 1fr}
  .featured-card.large{grid-row:span 1}
  .featured-card.large .featured-visual{height:200px}
  .posts-grid{grid-template-columns:repeat(2,1fr)}
  .footer-grid{grid-template-columns:repeat(3,1fr)}
  .cta-section{flex-direction:column;text-align:center}
  .cta-main{max-width:100%}
  .cta-buttons{justify-content:center}
}
@media(max-width:768px){
  .header-inner{padding:0 16px}
  .nav-links{display:none}
  .featured-grid{grid-template-columns:1fr}
  .posts-grid{grid-template-columns:1fr}
  .filters-section{flex-direction:column;align-items:stretch;gap:12px}
  .search-box{width:100%}
  .filter-pills{overflow-x:auto;flex-wrap:nowrap;padding-bottom:4px;-webkit-overflow-scrolling:touch}
  .pill{flex-shrink:0}
  .hero-title{font-size:28px}
  .cta-section{padding:36px 24px;border-radius:var(--radius-lg)}
  .cta-headline{font-size:22px}
  .footer-grid{grid-template-columns:repeat(2,1fr)}
  .footer-bottom{flex-direction:column;gap:16px;align-items:flex-start}
}
</style>
</head>
